import{_ as e,o as d,c as a,ag as i}from"./chunks/framework.BPmc_f4o.js";const u=JSON.parse('{"title":"Avantes Spectrometer Driver","description":"Reference for the Avantes spectrometer driver — USB/Ethernet AvaSpec control with full colorimetry, horticulture photon-flux bins, CRI (Ra + R1-R14), peak and dominant wavelength, and auto integration time.","frontmatter":{"title":"Avantes Spectrometer Driver","description":"Reference for the Avantes spectrometer driver — USB/Ethernet AvaSpec control with full colorimetry, horticulture photon-flux bins, CRI (Ra + R1-R14), peak and dominant wavelength, and auto integration time."},"headers":[],"relativePath":"reference/drivers/avantes.md","filePath":"reference/drivers/avantes.md"}'),r={name:"reference/drivers/avantes.md"};function s(o,t,n,c,l,h){return d(),a("div",null,[...t[0]||(t[0]=[i(`<h1 id="avantes" tabindex="-1">Avantes <a class="header-anchor" href="#avantes" aria-label="Permalink to &quot;Avantes&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">Not yet available</p><p>This driver is not published yet. It exists in the source tree for local use and is not on the marketplace or in the Extensions panel; this page documents it ahead of release.</p></div><p><strong>Driver for Avantes AvaSpec spectrometers over USB or Ethernet.</strong> Talks to the device via the native Avantes SDK (<code>avaspecx64.dll</code>) using P/Invoke, takes calibrated irradiance measurements, and exposes a full lighting / horticulture / colorimetry report as cached properties.</p><p>Avantes is a premium tier-3 extension driver. It ships as a signed <code>.muxdriver</code> and installs into <code>workspace/drivers/</code>.</p><h2 id="measurement-flow" tabindex="-1">Measurement flow <a class="header-anchor" href="#measurement-flow" aria-label="Permalink to &quot;Measurement flow&quot;">​</a></h2><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 1. Cover the entrance optic and capture a dark reference once per integration time.</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> spec.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">measureDark</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 2. (Optional) Let the driver pick a safe integration time for the current scene.</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> spec.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">autoIntegrationTime</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({ targetFraction: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.7</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> });</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 3. Take the measurement. measure() returns only status —</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">//    { isSaturated, peakCounts, integrationTime } — and refreshes all derived caches.</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> spec.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">measure</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 4. Read derived numbers as plain properties — no further device calls.</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> cct</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">      =</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> spec.cct;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> cri</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">      =</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> spec.cri;           </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Ra</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> indices</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  =</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> spec.colorRendering; </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// [R1..R14], R9 at index 8</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> lux</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">      =</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> spec.illuminance;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> ppfd</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">     =</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> spec.ppf;          </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 400-700 nm</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> blueFlux</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> spec.photonFlux400_500;</span></span></code></pre></div><p><code>measure()</code> deliberately returns only minimal status so it stays cheap for the AI to call repeatedly; the full lighting / colour report is read from the cached properties afterwards. The AI can answer &quot;measure CCT&quot; by calling <code>measure()</code> and reading <code>cct</code> — it does not need to fetch the spectrum.</p><p>All numeric output (scalars and arrays) is rounded to the <code>significantDigits</code> config setting (default <code>4</code>).</p><h2 id="derived-metrics" tabindex="-1">Derived metrics <a class="header-anchor" href="#derived-metrics" aria-label="Permalink to &quot;Derived metrics&quot;">​</a></h2><p>All cached on every <code>measure()</code>. Properties return <code>NaN</code> (or <code>0</code> for non-negative fluxes) when a metric isn&#39;t meaningful for the current spectrum (e.g. <code>cct</code> on a pure laser line).</p><h3 id="lighting" tabindex="-1">Lighting <a class="header-anchor" href="#lighting" aria-label="Permalink to &quot;Lighting&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Property</th><th>Unit</th><th>Description</th></tr></thead><tbody><tr><td><code>cct</code></td><td>K</td><td>Correlated colour temperature (McCamy approximation). NaN when chromaticity is more than 0.05 Δuv from the Planckian locus.</td></tr><tr><td><code>cieX</code>, <code>cieY</code></td><td>—</td><td>CIE 1931 2° chromaticity coordinates.</td></tr><tr><td><code>illuminance</code></td><td>lx</td><td>Photopic V(λ)-weighted irradiance (683 lm/W × ∫ V(λ) E(λ) dλ).</td></tr><tr><td><code>luminousFlux</code></td><td>lm</td><td>Same integration as <code>illuminance</code>; differs only in the per-area interpretation of the input.</td></tr><tr><td><code>cri</code></td><td>—</td><td>CIE 13.3-1995 general colour rendering index (Ra, average of R1-R8). NaN when |Duv| &gt; 0.0054.</td></tr><tr><td><code>colorRendering</code></td><td>—</td><td>Array of the 14 CIE 13.3 special indices <code>[R1…R14]</code>. R9 (deep red) is at index 8 (zero-based). Empty when CRI is undefined.</td></tr><tr><td><code>peakWavelength</code></td><td>nm</td><td>Wavelength of maximum spectral irradiance, parabolic-refined.</td></tr><tr><td><code>dominantWavelength</code></td><td>nm</td><td>Spectral colour the source matches; negative value means complementary (purples).</td></tr></tbody></table><h3 id="horticulture-photon-flux-bins" tabindex="-1">Horticulture photon-flux bins <a class="header-anchor" href="#horticulture-photon-flux-bins" aria-label="Permalink to &quot;Horticulture photon-flux bins&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Property</th><th>Band (nm)</th><th>Use</th></tr></thead><tbody><tr><td><code>photonFlux300_400</code></td><td>300-400</td><td>UV-A / UV-B</td></tr><tr><td><code>photonFlux400_500</code></td><td>400-500</td><td>Blue</td></tr><tr><td><code>photonFlux500_600</code></td><td>500-600</td><td>Green</td></tr><tr><td><code>photonFlux600_700</code></td><td>600-700</td><td>Red</td></tr><tr><td><code>photonFlux700_800</code></td><td>700-800</td><td>Far-red</td></tr><tr><td><code>photonFlux800_1000</code></td><td>800-1000</td><td>Near-IR</td></tr><tr><td><code>ppf</code></td><td>400-700</td><td>PAR / PPFD (already present)</td></tr><tr><td><code>photonFlux400_800</code></td><td>400-800</td><td>Extended PAR (already present)</td></tr></tbody></table><p>All fluxes in µmol/s (or µmol/(s·m²) if the calibration is per area). For arbitrary bands use the <code>getPhotonFlux</code> action.</p><h2 id="properties" tabindex="-1">Properties <a class="header-anchor" href="#properties" aria-label="Permalink to &quot;Properties&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Property</th><th>Type</th><th>Access</th><th>Unit</th><th>Description</th></tr></thead><tbody><tr><td><code>connected</code></td><td>bool</td><td>R</td><td>—</td><td>Device connection status</td></tr><tr><td><code>serial</code></td><td>string</td><td>R</td><td>—</td><td>Connected device serial</td></tr><tr><td><code>nrPixels</code></td><td>int</td><td>R</td><td>—</td><td>Sensor pixel count</td></tr><tr><td><code>integrationTime</code></td><td>double</td><td>R/W</td><td>ms</td><td>Integration time (a.k.a. exposure)</td></tr><tr><td><code>averages</code></td><td>int</td><td>R/W</td><td>—</td><td>Hardware averages per measurement</td></tr><tr><td><code>wavelengths</code></td><td>double[]</td><td>R</td><td>nm</td><td>Wavelength axis (raw or interpolated grid)</td></tr><tr><td><code>spectrum</code></td><td>double[]</td><td>R</td><td>counts</td><td>Raw counts from last measurement</td></tr><tr><td><code>dark</code></td><td>double[]</td><td>R</td><td>counts</td><td>Dark reference data</td></tr><tr><td><code>irradiance</code></td><td>double[]</td><td>R</td><td>µW/nm</td><td>Calibrated irradiance</td></tr><tr><td><code>isSaturated</code></td><td>bool</td><td>R</td><td>—</td><td>Saturation detected in last measurement</td></tr><tr><td><code>peakCounts</code></td><td>double</td><td>R</td><td>counts</td><td>Maximum counts in last measurement</td></tr><tr><td><code>darkCorrected</code></td><td>bool</td><td>R</td><td>—</td><td>Whether a dark reference is loaded</td></tr><tr><td><code>calibrationInfo</code></td><td>string</td><td>R</td><td>—</td><td>Description of loaded calibration</td></tr><tr><td><code>radiantPower</code></td><td>double</td><td>R</td><td>W</td><td>Total radiant power 350-850 nm</td></tr><tr><td><code>temperature</code></td><td>double</td><td>R</td><td>°C</td><td>Detector temperature</td></tr><tr><td><code>streaming</code></td><td>bool</td><td>R/W</td><td>—</td><td>Continuous streaming enabled</td></tr><tr><td><code>firmwareVersion</code>, <code>fpgaVersion</code></td><td>string</td><td>R</td><td>—</td><td>Device firmware / FPGA versions</td></tr></tbody></table><p>…plus all derived metrics in the section above.</p><h2 id="actions" tabindex="-1">Actions <a class="header-anchor" href="#actions" aria-label="Permalink to &quot;Actions&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Args</th><th>Description</th></tr></thead><tbody><tr><td><code>measure</code></td><td>—</td><td>Take a single measurement; updates the full derived report</td></tr><tr><td><code>measureDark</code></td><td>—</td><td>Capture a dark reference at the current integration time</td></tr><tr><td><code>clearDark</code></td><td>—</td><td>Discard the dark reference</td></tr><tr><td><code>autoIntegrationTime</code></td><td><code>{ targetFraction?, maxIterations?, minMs?, maxMs? }</code></td><td>Iteratively adjust <code>integrationTime</code> so peak counts hit <code>targetFraction</code> of full scale (default 0.7)</td></tr><tr><td><code>loadCalibration</code></td><td><code>{ source }</code></td><td><code>&quot;eeprom&quot;</code> or path to a calibration text file</td></tr><tr><td><code>getRadiantPower</code></td><td><code>{ min, max }</code></td><td>Radiant power (W) over an arbitrary band</td></tr><tr><td><code>getPhotonFlux</code></td><td><code>{ min, max }</code></td><td>Photon flux (µmol/s) over an arbitrary band</td></tr><tr><td><code>discover</code></td><td>—</td><td>List available Avantes devices on USB and Ethernet</td></tr><tr><td><code>connect</code></td><td><code>{ serial? }</code></td><td>Connect to a specific device, or the first available</td></tr><tr><td><code>disconnect</code></td><td>—</td><td>Disconnect</td></tr><tr><td><code>startStream</code>, <code>stopStream</code></td><td>—</td><td>Continuous measurement streaming</td></tr><tr><td><code>getVersionInfo</code></td><td>—</td><td>Firmware / FPGA / DLL versions</td></tr></tbody></table><h2 id="config-options" tabindex="-1">Config options <a class="header-anchor" href="#config-options" aria-label="Permalink to &quot;Config options&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>connectionType</code></td><td>string</td><td><code>&quot;usb&quot;</code></td><td><code>&quot;usb&quot;</code> or <code>&quot;eth&quot;</code></td></tr><tr><td><code>serial</code></td><td>string</td><td><code>&quot;&quot;</code></td><td>Target device serial — empty = first available</td></tr><tr><td><code>integrationTime</code></td><td>double</td><td><code>100</code></td><td>Integration time in ms</td></tr><tr><td><code>averages</code></td><td>int</td><td><code>1</code></td><td>Hardware averages per measurement</td></tr><tr><td><code>useHighResAdc</code></td><td>bool</td><td><code>true</code></td><td>Enable 16-bit ADC mode (when supported)</td></tr><tr><td><code>calibrationSource</code></td><td>string</td><td><code>&quot;eeprom&quot;</code></td><td><code>&quot;eeprom&quot;</code> or path to a calibration file</td></tr><tr><td><code>interpolate</code></td><td>bool</td><td><code>true</code></td><td>Resample to a uniform wavelength grid</td></tr><tr><td><code>interpolateMin/Max/Step</code></td><td>double</td><td><code>350</code>/<code>850</code>/<code>1</code></td><td>Interpolation grid (nm)</td></tr><tr><td><code>strayLightCorrection</code></td><td>bool</td><td><code>false</code></td><td>Use <code>AVS_SuppressStrayLight</code> if available</td></tr><tr><td><code>strayLightFactor</code></td><td>double</td><td><code>1.0</code></td><td>Stray-light multiplier</td></tr><tr><td><code>streamIntervalMs</code></td><td>int</td><td><code>1000</code></td><td>Streaming interval</td></tr><tr><td><code>autoIntegration</code></td><td>bool</td><td><code>false</code></td><td>When <code>true</code>, every <code>measure()</code> runs <code>autoIntegrationTime</code> first (skipped while a dark reference is loaded)</td></tr><tr><td><code>significantDigits</code></td><td>int</td><td><code>4</code></td><td>Significant figures applied to all numeric output (scalars and arrays, including the wavelength axis). Set <code>0</code> to disable rounding</td></tr></tbody></table><h2 id="notes-on-accuracy" tabindex="-1">Notes on accuracy <a class="header-anchor" href="#notes-on-accuracy" aria-label="Permalink to &quot;Notes on accuracy&quot;">​</a></h2><ul><li><strong>CCT / CRI / dominant wavelength</strong> are only meaningful for broadband white-ish sources. For monochromatic sources (lasers, narrow-band LEDs) these will return NaN or be reported as off-locus.</li><li><strong>Dark reference is per-integration-time.</strong> Retake the dark whenever you change <code>integrationTime</code> — <code>autoIntegrationTime</code> is therefore skipped while a dark is loaded.</li><li>The McCamy CCT approximation is accurate to ±2 K for 2856-6500 K and degrades gracefully outside that range. For laboratory-grade accuracy, post-process the raw <code>irradiance</code> array.</li><li>CRI uses the CIE 13.3-1995 procedure (14 TCS samples, Planckian &lt; 5000 K / D-illuminant ≥ 5000 K reference, von-Kries chromatic adaptation, CIE 1964 U*V*W* differences). It computes <code>[Ra, R1…R14]</code> internally; <code>cri</code> exposes Ra and <code>colorRendering</code> exposes the special indices <code>[R1…R14]</code> (R9 at index 8).</li></ul>`,24)])])}const k=e(r,[["render",s]]);export{u as __pageData,k as default};
